from functools import wraps
def log_call(fn):
    @wraps(fn)
    def wrapper(*a, **k):
        print(f'Calling {fn.__name__}')
        r = fn(*a, **k)
        print(f'Finished {fn.__name__}')
        return r
    return wrapper

from functools import wraps
def repeat(times):
    def deco(fn):
        @wraps(fn)
        def wrapper(*a, **k):
            for _ in range(times):
                fn(*a, **k)
        return wrapper
    return deco

from functools import wraps
def uppercase(fn):
    @wraps(fn)
    def wrapper(*a, **k):
        return fn(*a, **k).upper()
    return wrapper
@uppercase
def greet():
    return 'Hello Kakade'
print(greet())
